"""Thin, cached, concurrent wrapper around OpenRouter chat completions."""
import hashlib, json, os, threading, time
from concurrent.futures import ThreadPoolExecutor
from openai import OpenAI

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CACHE = os.path.join(ROOT, "data", "llm_cache.jsonl")
_lock = threading.Lock()
_cache = {}
if os.path.exists(CACHE):
    for l in open(CACHE):
        try:
            d = json.loads(l)
            _cache[d["k"]] = d["v"]
        except Exception:
            pass
client = OpenAI(base_url="https://openrouter.ai/api/v1", api_key=os.environ["OPENROUTER_KEY"])


def chat(model, messages, temperature=0.0, max_tokens=600):
    k = hashlib.sha256(json.dumps([model, messages, temperature, max_tokens]).encode()).hexdigest()
    if k in _cache:
        return _cache[k]
    for attempt in range(6):
        try:
            r = client.chat.completions.create(model=model, messages=messages, temperature=temperature,
                                               max_tokens=max_tokens)
            v = r.choices[0].message.content
            if v is None:
                raise RuntimeError("empty")
            break
        except Exception as e:
            time.sleep(2 ** attempt)
            v = None
    if v is None:
        return None
    with _lock:
        _cache[k] = v
        with open(CACHE, "a") as f:
            f.write(json.dumps({"k": k, "v": v}) + "\n")
    return v


def chat_many(model, list_of_messages, workers=16, **kw):
    with ThreadPoolExecutor(workers) as ex:
        return list(ex.map(lambda m: chat(model, m, **kw), list_of_messages))

